fn pack(r: i32, g: i32, b: i32) -> i32 {
    (r % 256) * 65536 + (g % 256) * 256 + (b % 256)
}

fn red(c: i32) -> i32 {
    (c / 65536) % 256
}

fn green(c: i32) -> i32 {
    (c / 256) % 256
}

fn blue(c: i32) -> i32 {
    c % 256
}

fn dim(c: i32, pct: i32) -> i32 {
    pack(red(c) * pct / 100, green(c) * pct / 100, blue(c) * pct / 100)
}

fn dims() -> i32 {
    (256 << 16) | 128
}

fn frame(t: i32) {
    host::display::clear(0x000000);
    host::display::draw_string(8, 8, "LIB COLOR", 0xffffff, 2);
    host::display::draw_string(8, 32, "PACK RED GREEN BLUE", 0x00ff66, 1);
    host::display::draw_string(8, 46, "DIM(C,PCT)", 0x00ff66, 1);
    let base: i32 = pack(255, 96, 32);
    let mut i: i32 = 0;
    while i < 5 {
        host::display::fill_rect(8 + i * 48, 64, 40, 40, dim(base, 100 - i * 20));
        i = i + 1;
    }
    host::display::present();
}
